#include <iostream>
#include <vector>
#include <cstddef>

// Template demonstrating nontype parameter (Capacity) and default type parameter (Storage)
template <typename T, std::size_t Capacity = 4>
class FixedBuffer {
private:
    T data[Capacity];
    std::size_t count = 0;
public:
    bool push(const T& val) {
        if (count >= Capacity) return false;
        data[count++] = val;
        return true;
    }

    std::size_t size() const { return count; }
    std::size_t max_size() const { return Capacity; }

    T get(std::size_t idx) const { return data[idx]; }
};

int main() {
    // Using default capacity (4)
    FixedBuffer<int> bufDefault;
    bufDefault.push(10);
    bufDefault.push(20);

    // Specifying nontype argument explicitly (2)
    FixedBuffer<double, 2> bufCustom;
    bufCustom.push(1.5);
    bufCustom.push(2.5);
    bool overflow = bufCustom.push(3.5); // Should fail

    std::cout << "Default buf size: " << bufDefault.size() << "/" << bufDefault.max_size() << "\n";
    std::cout << "Custom buf size: " << bufCustom.size() << "/" << bufCustom.max_size() << "\n";
    std::cout << "Overflow rejected: " << (overflow ? "false" : "true") << "\n";
    return 0;
}

#include <iostream>

// Generic function template for single value
template <typename T>
void display(const T& val) {
    std::cout << "Template 1 (single): " << val << "\n";
}

// Overloaded function template for pair of values
template <typename T, typename U>
void display(const T& a, const U& b) {
    std::cout << "Template 2 (pair): (" << a << ", " << b << ")\n";
}

// Non-template function overload for int specifically
void display(int val) {
    std::cout << "Non-template (int): " << val << "\n";
}

int main() {
    display(3.14);       // Calls Template 1 with double
    display(100);        // Calls Non-template function (preferred over Template 1)
    display("Key", 42);  // Calls Template 2 with const char* and int
    return 0;
}
